Функция ПолучитьДебетовыйОборотПоКонтрагенту(СчетСсылка, КонтрагентСсылка) Экспорт

	НомерСубконтоКонтрагент = 0;
	Для НомерСубконто = 1 По СчетСсылка.ВидыСубконто.Количество() Цикл
		ВидСубконто = СчетСсылка.ВидыСубконто[НомерСубконто - 1].ВидСубконто;
		Если ВидСубконто.ТипЗначения.СодержитТип(Тип("СправочникСсылка.Контрагенты")) Тогда
			НомерСубконтоКонтрагент = НомерСубконто;
			Прервать;
		КонецЕсли;
	КонецЦикла;

	Если НомерСубконтоКонтрагент = 0 Тогда
		Возврат 0;
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	СУММА(Движения.Сумма) КАК Сумма
	|ИЗ
	|	РегистрБухгалтерии.Хозрасчетный.ДвиженияССубконто(, , СчетДт = &Счет) КАК Движения
	|ГДЕ
	|	Движения.СубконтоДт" + Формат(НомерСубконтоКонтрагент, "ЧГ=0") + " = &Контрагент";

	Запрос.УстановитьПараметр("Счет", СчетСсылка);
	Запрос.УстановитьПараметр("Контрагент", КонтрагентСсылка);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() И Выборка.Сумма <> Null Тогда
		Возврат Выборка.Сумма;
	КонецЕсли;

	Возврат 0;

КонецФункции
